<div class="page-title clearfix"><h1>Pago administrativo #<?php echo (int)$payment->id; ?></h1><a href="<?php echo get_uri('invoice_payments'); ?>" class="btn btn-default pull-right">Volver a pagos</a></div>
<div class="row"><div class="col-md-7"><div class="card"><div class="card-header"><h4>Datos del pago</h4></div><div class="card-body"><table class="table"><tr><th>Cliente</th><td><?php echo esc($payment->client_name); ?></td></tr><tr><th>Fecha</th><td><?php echo format_to_date($payment->payment_date,false); ?></td></tr><tr><th>Monto</th><td><?php echo to_currency($payment->amount); ?></td></tr><tr><th>Forma de pago</th><td><?php echo esc($payment->payment_method_title); ?></td></tr><tr><th>Cuenta de destino</th><td><?php echo esc($payment->financial_account_name); ?></td></tr><tr><th>Referencia</th><td><?php echo esc($payment->reference?:'-'); ?></td></tr><tr><th>Notas</th><td><?php echo esc($payment->note?:'-'); ?></td></tr><tr><th>Estado</th><td><?php echo $payment->status==='active'?'Activo':'Cancelado'; ?></td></tr></table></div></div></div>
<div class="col-md-5"><div class="card"><div class="card-header"><h4>Resumen</h4></div><div class="card-body"><div class="row text-center"><div class="col-md-4"><b>Monto recibido</b><br><?php echo to_currency($payment->amount); ?></div><div class="col-md-4"><b>Aplicado</b><br><?php echo to_currency($applied); ?></div><div class="col-md-4"><b>Disponible</b><br><strong id="available-summary"><?php echo to_currency($available); ?></strong></div></div></div></div></div></div>
<div class="card mt15"><div class="card-header"><h4>Aplicaciones activas</h4></div><div class="table-responsive"><table class="table"><thead><tr><th>Venta</th><th>Fecha</th><th>Total venta</th><th>Aplicado con este pago</th><th>Saldo venta</th><th></th></tr></thead><tbody><?php foreach($allocations as$a): ?><tr><td><a href="<?php echo get_uri('invoices/view/'.$a->invoice_id); ?>"><?php echo esc($a->display_id ?: 'Venta #'.$a->invoice_id); ?></a></td><td><?php echo format_to_date($a->bill_date,false); ?></td><td><?php echo to_currency($a->total); ?></td><td><?php echo to_currency($a->amount_applied); ?></td><td><?php echo to_currency($a->outstanding); ?></td><td><?php echo form_open('invoice_payments/delete_allocation',['class'=>'general-form remove-allocation-form']); ?><?php echo csrf_field(); ?><input type="hidden" name="id" value="<?php echo(int)$a->id; ?>"><input type="hidden" name="reason" value="Retirada desde detalle del pago"><button class="btn btn-danger btn-xs">Quitar</button><?php echo form_close(); ?></td></tr><?php endforeach; ?><?php if(!$allocations): ?><tr><td colspan="6" class="text-center text-muted">El pago todavía no tiene aplicaciones.</td></tr><?php endif; ?></tbody></table></div></div>
<?php if($payment->status==='active'&&bccomp($available,'0',6)>0): ?><div class="card mt15" id="apply"><div class="card-header"><h4>Aplicar pago a ventas</h4></div><div class="card-body"><div class="alert alert-info">Disponible: <strong><?php echo to_currency($available); ?></strong>. Se muestran todas las ventas administrativas vigentes del cliente que tienen saldo pendiente.</div><?php echo form_open('invoice_payments/apply_multiple',['id'=>'multi-allocation-form','class'=>'general-form']); ?><?php echo csrf_field(); ?><input type="hidden" name="payment_id" value="<?php echo(int)$payment->id; ?>"><table class="table"><thead><tr><th>Venta</th><th>Fecha</th><th>Total</th><th>Aplicado</th><th>Saldo pendiente</th><th>Aplicar</th></tr></thead><tbody><?php foreach($sales as$sale): ?><tr><td><?php echo esc($sale->display_id ?: 'Venta #'.$sale->id); ?><input type="hidden" name="sale_id[]" value="<?php echo(int)$sale->id; ?>"></td><td><?php echo format_to_date($sale->bill_date,false); ?></td><td><?php echo to_currency($sale->total); ?></td><td><?php echo to_currency($sale->paid_amount); ?></td><td><?php echo to_currency($sale->outstanding); ?></td><td><input name="amount_applied[]" value="0" class="form-control allocation-input" inputmode="decimal" data-max="<?php echo esc($sale->outstanding); ?>"></td></tr><?php endforeach; ?><?php if(!$sales): ?><tr><td colspan="6" class="text-center text-muted">El cliente no tiene ventas pendientes.</td></tr><?php endif; ?></tbody></table><div class="text-end"><b>Total seleccionado: <span id="selected-total">$0.00</span></b> / Disponible <?php echo to_currency($available); ?> <button class="btn btn-primary ms10" <?php echo $sales?'':'disabled'; ?>>Guardar aplicaciones</button></div><?php echo form_close(); ?></div></div><?php endif; ?>
<script>$(function(){var available=parseFloat('<?php echo $available; ?>');function total(){var t=0;$('.allocation-input').each(function(){var v=parseFloat($(this).val()||0),m=parseFloat($(this).data('max')||0);if(v>m){$(this).addClass('is-invalid');}else{$(this).removeClass('is-invalid');}t+=isNaN(v)?0:v;});$('#selected-total').text('$'+t.toFixed(2)).toggleClass('text-danger',t>available);return t;}$('.allocation-input').on('input',total);$('#multi-allocation-form').appForm({beforeAjaxSubmit:function(){if(total()>available){appAlert.error('El total excede el disponible del pago.');return false;}},onSuccess:function(r){if(r.success)location.reload();else appAlert.error(r.message);}});$('.remove-allocation-form').appForm({onSuccess:function(r){if(r.success)location.reload();else appAlert.error(r.message);}});});</script>
